def decide_based_on_prime(prime: int, a, b):
    """
    Given an integer 'prime' and two values a and b,
    return a if 'prime' is a prime number, otherwise return b.
    """
    if prime < 2:
        return b
    if prime == 2:
        return a
    if prime % 2 == 0:
        return b

    # Check for primes greater than 2
    limit = int(prime ** 0.5) + 1
    for i in range(3, limit, 2):
        if prime % i == 0:
            return b
    return a
