def convert_to_base(n, base):
    if n == 0:
        return "0"
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if base < 2 or base > len(digits):
        raise ValueError("Base must be between 2 and 36")
    negative = n < 0
    n = abs(n)
    res = []
    while n:
        res.append(digits[n % base])
        n //= base
    if negative:
        res.append('-')
    return ''.join(reversed(res))

