def is_valid_filename(filename: str) -> bool:
    import re
    # Common rules for filenames:
    # 1. Not empty
    if not filename:
        return False
    # 2. Not contain path separators (for simplicity, both Unix and Windows)
    if '/' in filename or '\\' in filename:
        return False
    # 3. Not contain null bytes
    if '\x00' in filename:
        return False
    # 4. No reserved names on Windows (like CON, PRN, AUX, NUL, COM1, LPT1, etc.)
    reserved_names = {
        "CON", "PRN", "AUX", "NUL",
        *(f"COM{i}" for i in range(1, 10)),
        *(f"LPT{i}" for i in range(1, 10)),
    }
    # Strip extension and uppercase without extension
    name_only = filename.rsplit('.', 1)[0].upper()
    if name_only in reserved_names:
        return False
    # 5. No invalid characters (on Windows): <>:"/\|?* and non-printable characters
    # We'll check no control characters and no <>:"/\|?* characters
    if re.search(r'[\x00-\x1f<>:"/\\|?*]', filename):
        return False
    # 6. Length limits: length > 255 are usually invalid filesystems
    if len(filename) > 255:
        return False
    return True

