def can_split_array(nums, n, m):
    """
    Determines if the array `nums` can be split into `n` subarrays where each subarray is either:
    - one element long, OR
    - has a sum at least `m`.

    Splitting rules:
    - You can split an array into two as long as it has at least two elements.

    Returns True if possible, else False.
    """
    from functools import lru_cache

    if n > len(nums):
        return False  # can't split into more parts than elements

    prefix_sum = [0]
    for x in nums:
        prefix_sum.append(prefix_sum[-1] + x)

    @lru_cache(None)
    def dfs(start, parts):
        if parts == 1:
            length = len(nums) - start
            s = prefix_sum[len(nums)] - prefix_sum[start]
            return length == 1 or s >= m

        # Try all valid splits
        # Must leave at least parts - 1 elements for the remaining parts (each at least one element)
        for end in range(start, len(nums) - (parts - 1)):
            length = end - start + 1
            s = prefix_sum[end + 1] - prefix_sum[start]

            if length == 1 or s >= m:
                if dfs(end + 1, parts - 1):
                    return True
        return False

    return dfs(0, n)

